<?php defined('ABSPATH') || exit;$base=home_url('/companion/');$root='dungeon-master/campaigns/'.$campaign->id().'/locations'; ?>
<section class="gmrc-gazetteer"><header class="gmrc-gazetteer__hero"><div><p class="gmrc-dm-desk__eyebrow"><?php echo esc_html($location->typeLabel()); ?> · <?php echo $location->isKeeperOnly()?'Keeper only':'Player-visible'; ?><?php echo $location->isArchived()?' · Archived':''; ?></p><h1><?php echo esc_html($location->name()); ?></h1><?php if($parent): ?><p>Within <a href="<?php echo esc_url(add_query_arg('gmrc_route',$root.'/'.$parent->id(),$base)); ?>"><?php echo esc_html($parent->name()); ?></a></p><?php endif; ?></div><?php if(!$campaign->isArchived()&&!$location->isArchived()): ?><a class="gmrc-gazetteer-button" href="<?php echo esc_url(add_query_arg('gmrc_route',$root.'/'.$location->id().'/edit',$base)); ?>">Edit Place</a><?php endif; ?></header>
<article class="gmrc-gazetteer-page"><section><h2>At a glance</h2><p><?php echo $location->summary()!==''?esc_html($location->summary()):'No summary has been written yet.'; ?></p></section><section><h2>Keeper’s notes</h2><div><?php echo $location->notes()!==''?wpautop(esc_html($location->notes())):'<p>No private notes have been written yet.</p>'; ?></div></section><section class="gmrc-gazetteer-page__map"><h2>Cartographer’s Bench</h2><p><?php echo $location->tabletopSceneId()!==''?'A Tabletop scene is linked to this place.':'No Tabletop scene is linked yet. The Gazetteer identity is ready for the future GMRT Cartographer bridge.'; ?></p></section></article>
<?php if($children!==[]): ?><section class="gmrc-gazetteer-children"><h2>Places within <?php echo esc_html($location->name()); ?></h2><div class="gmrc-gazetteer-grid"><?php foreach($children as $child): ?><article class="gmrc-gazetteer-card"><p class="gmrc-gazetteer-card__parent"><?php echo esc_html($child->typeLabel()); ?></p><h3><?php echo esc_html($child->name()); ?></h3><a href="<?php echo esc_url(add_query_arg('gmrc_route',$root.'/'.$child->id(),$base)); ?>">Open place →</a></article><?php endforeach; ?></div></section><?php endif; ?>
<?php if(!$campaign->isArchived()&&!$location->isArchived()): ?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" class="gmrc-gazetteer-archive-form" onsubmit="return confirm('Archive this Gazetteer location?');"><input type="hidden" name="action" value="gmrc_app_request"><input type="hidden" name="gmrc_route" value="<?php echo esc_attr($root.'/'.$location->id().'/archive'); ?>"><input type="hidden" name="_method" value="POST"><input type="hidden" name="gmrc_nonce" value="<?php echo esc_attr(wp_create_nonce('gmrc_dm_gazetteer_'.$campaign->id())); ?>"><button type="submit">Archive place</button></form><?php endif; ?><p class="gmrc-gazetteer-back"><a href="<?php echo esc_url(add_query_arg('gmrc_route',$root,$base)); ?>">← Back to Keeper’s Gazetteer</a></p></section>
